"use strict";
var PurdyChat = (function(window, undefined) {

  console.log('PurdyChat');
  var ERROR_REQUERIDO = 'Este campo es requerido';
  var ERROR_EMAIL = 'El correo electronico no es valido';
  var myConfig = {};
  var param;
  var chat_open = false;
  var message = {
      "text1": "¿Listo para tener el carro de tus sueños?",
      "text2": "Estamos aquí para ayudarte."
    };
  var list_departments = {
    '183b854294ab3df3169323286fdca483': 'Ventas Vehículos Nuevos',
    '27e1adfecbb8bb33f863dc3441cad29c': 'Ventas Vehículos Usados',
    'c7924fa0b96c1ca5a241f0eb898bf622': 'Citas de Talleres',
    '8bf56d8c0a950d22c2a84d67b398ef6f': 'Repuestos y accesorios'
  };

  function initialize(paramInput) {
    param = paramInput;
    myConfig = {
      deparment: param.deparment ? param.deparment : 'c7924fa0b96c1ca5a241f0eb898bf622',
      isused: param.used ? true : false
    };
    
    var nodo = $('#messages-chat');

    if(nodo.size()){        
        message = nodo.data('messageschat');
    }

    addHtml();

  }

  function renderTemplate(url, param) {
    // var template = promiseajax(url);
    var response = '<div class="purdy-chat-wraper ' + param['classState'] + '">' +
                            '<div class="toolbar-container">' +
                                '<div class="popup_chat">' +
                                    '<div><a href="javascript:void(0);" id="evt-chat_purdy_close">x</a></div>' +
                                    '<p>'+message['text1']+'</p>' +
                                    '<span>'+message['text2']+'</span>' +
                                '</div>' +
                                '<a class="chat-btn btn-chat-icon open-chat-icon close-chat">_</a>' +
                                '<a class="chat-btn close-chat">Ingresá aquí al Chat</a>' +
                            '</div>' +
                            '<div class="wrap-notificarion-sale">' +
                                '<div class="info">' +
                                    '<p><strong>¿Querés comprar un <span class="name-auto-widget">' + param['vehicleName'] + ' ?</span></strong> Estamos aquí para ayudarte con cualquier duda que tengás</p>' +
                                    '<a class="btn-init hidden-notificarion-widget">Comenzar Chat</a>' +
                                '</div>' +
                            '</div>' +
                            '<div class="chat-middle-wrapper">' +
                                '<span>Bienvenido a Grupo Purdy Motor</span>' +
                                '<div class="chat-form-wrapper">' +
                                    '<div class="chat_txt_wrapper clearfix" >' +
                                        '<input id="chat-purdy-name" placeholder="Nombre Completo" type="text"/>' +
                                        '<span class="span-error" id="error-chat-purdy-name"></span>' +
                                    '</div>' +
                                    '<div class="chat_txt_wrapper" >' +
                                        '<input id="chat-purdy-email" placeholder="Correo Electrónico" type="text"/>' +
                                        '<span class="span-error" id="error-chat-purdy-email"></span>' +
                                    '</div>' +
                                    '<div class="chat_txt_wrapper clearfix">' +
                                        '<input id="chat-purdy-document-number" placeholder="Número de identificación" type="text"/>' +
                                    '</div>' +
                                    '<div class="chat_txt_wrapper clearfix">' +
                                        '<input id="chat-purdy-phone" placeholder="Teléfono" type="text"/>' +
                                        '<span class="span-error" id="error-chat-purdy-phone"></span>' +
                                    '</div>' +
                                    '<div class="chat_txt_wrapper clearfix error" >' +
                                        '<input id="chat-purdy-plate" placeholder="Número de Placa" type="text"/>' +
                                    '</div>' +
                                    '<div class="chat_txt_wrapper clearfix">' +
                                        '<span> Seleccione el departamento con el que desea comunicarse </span>' +
                                    '</div>' +
                                    '<div class="chat_txt_wrapper clearfix">' +
                                        '<select id="chat-purdy-deparment"> </select>' +
                                    '</div>' +
                                    '<div class="chat_txt_wrapper clearfix">' +
                                        '<input type="button" value="Comenzar Chat" id="btn-start-chat-purdy"/>' +
                                    '</div>' +
                                '</div>' +
                            '</div>' +
                        '</div>';

    // template.then(function (data) {
    //             response = data;

    // $.each(param, function(key, val){
    //     response.replace('{[{'+ key + '}]}', val);
    // });

    appendHtml(document.body, response);
    addCss();
    
    loadDeparments();
    initializeButtons();
    //loadDeparments();
    clearErrors();

    // }, function(dataMarca){
    //     location.reload();
    // });


  }

  function promiseajax(url_send) {

    var deferred = $.Deferred();

    $.ajax({
      method: 'GET',
      url: url_send,
      success: function(dataReturn) {
        deferred.resolve(dataReturn);
      },
      error: function(dataReturn) {
        deferred.reject(dataReturn);
      }
    });
    return deferred.promise();

  }

  function addHtml() {
    var classState = 'normal-page';
    var vehicleName = $('.nombreCarro');
    var curreentSectionAuto = $('.evt-car-chat');

    if (curreentSectionAuto.size()) {
      var classState = 'vehicle-show';
    }

    //Valido que exista para definir el nombre
    vehicleName = vehicleName.size() ? vehicleName.first().text() : 'Vehiculo';
    return renderTemplate('/js/plugin-chat/purdy_chat.html', {
      'classState': classState,
      'vehicleName': vehicleName
    });

  }

  function appendHtml(el, str) {
    var div = document.createElement('div');
    div.innerHTML = str;
    while (div.children.length > 0) {
      el.appendChild(div.children[0]);
    }
  }

  function httpGet(theUrl) {
    var xmlHttp = null;

    xmlHttp = new XMLHttpRequest();
    xmlHttp.open("GET", theUrl, false);
    xmlHttp.send(null);
    return xmlHttp.responseText;
  }

  function addCss() {
    var cssId = 'purdy_chat'; // you could encode the css path itself to generate id..
    if (!document.getElementById(cssId)) {
      var head = document.getElementsByTagName('head')[0];
      var link = document.createElement('link');
      link.id = cssId;
      link.rel = 'stylesheet';
      link.type = 'text/css';
      link.href = 'http://toyotacr.com/purdy-chat/js/plugin-chat/css/purdy_chat.css?v=' + (Math.floor(Math.random() * 50) + 1);
      link.media = 'all';
      head.appendChild(link);
    }
  }

  function initializeButtons() {

    olark('api.chat.onMessageToVisitor', function(event) {
      document.getElementsByClassName('purdy-chat-wraper')[0].style.display = 'none';
    });

    var btnOpenChat = document.getElementById('emg_live_chat_chat_link');
    var btnToggleList = document.getElementsByClassName('chat-btn');

    // btnStartChat.addEventListener("click", toggleForm, false);
    $.each(btnToggleList, function(index, el) {
      $(el).on('click', toggleForm);
    });

    //btnOpenChat.preventDefault();

    //if (myConfig.isused == false) {
    //btnOpenChat.addEventListener("click", openChatForm, false);
    //}

    //var btnStartChat = document.getElementById('btn-start-chat-purdy');

    $('.hidden-notificarion-widget').on("click", function() {
      $('.purdy-chat-wraper').removeClass('vehicle-show');
    });

    $('#btn-start-chat-purdy').on("click", validateForm);
    // $.each( $('#btn-start-chat-purdy'), function(index, el) {
    // });
    olark('api.box.hide');
    timerChat();
  }

  function openChatForm() {
    // event.preventDefault();

    var btn = document.getElementsByClassName('btn-chat-icon')[0];
    var container = document.getElementsByClassName('chat-middle-wrapper')[0];
    var wrapChat = document.getElementsByClassName('purdy-chat-wraper')[0];

    // myConfig.chat_open = true;
    btn.classList.remove("open-chat-icon");
    btn.classList.remove("close-chat-icon");
    btn.classList.add("close-chat-icon");
    // container.style.display = 'block';
    container.classList.add("active-chat");
    wrapChat.classList.add("active");

  }

  function toggleForm() {
    var wrapChat = document.getElementsByClassName('purdy-chat-wraper')[0];
    var btn = document.getElementsByClassName('btn-chat-icon')[0];
    var container = document.getElementsByClassName('chat-middle-wrapper')[0];
    if (myConfig.chat_open) {
      myConfig.chat_open = false;
      btn.classList.remove("close-chat-icon");
      btn.classList.add("open-chat-icon");
      // container.style.display = 'none';
      wrapChat.classList.remove("active");
    } else {
      myConfig.chat_open = true;
      btn.classList.remove("open-chat-icon");
      btn.classList.add("close-chat-icon");
      // container.style.display = 'block';
      wrapChat.classList.add("active");
    }
  }

  function loadDeparments() {

    var selectDeparment = document.getElementById("chat-purdy-deparment");


    for (var deparment in list_departments) {
      var option = document.createElement("option");
      option.value = deparment;
      option.text = list_departments[deparment];
      if (deparment === myConfig.deparment) {
        option.selected = "selected";
      }
      selectDeparment.add(option);
    }
  }

  function clearErrors() {
    var inputs = document.getElementsByTagName('input');
    var errors = document.getElementsByClassName('span-error');
    
    for (var index = 0; index < errors.length; index++) {
      inputs[index].classList.remove("error");
    }

    
    for (var indexSecond = 0; indexSecond < errors.length; indexSecond++) {
      errors[indexSecond].innerHTML = '';
      errors[indexSecond].classList.remove("active");
    }
  }

  function validateForm() {
    clearErrors();
    var validname = validateName();
    var validphone = validatePhone();
    var validemail = validateEmail();

    if (validname && validphone && validemail) {
      startChat();
    }
  }

  function startChat() {

    var user_info = getUserInfo();


    olark('api.chat.setOperatorGroup', {
      group: user_info.group
    });
    olark('api.chat.updateVisitorStatus', {
      snippet: ['Departamento: ' + user_info.group_name,
        'Cédula: ' + user_info.id,
        'Placa: ' + user_info.plate,
        'Teléfono: ' + user_info.phone,
        'Email: ' + user_info.email,
        'Nombre: ' + user_info.name
      ]
    });

    olark('api.visitor.updateFullName', {
      fullName: user_info.name
    });

    olark('api.visitor.updateEmailAddress', {
      emailAddress: user_info.email
    });

    olark('api.visitor.updatePhoneNumber', {
      phoneNumber: user_info.phone
    });

    document.getElementsByClassName('purdy-chat-wraper')[0].style.display = 'none';
    olark.configure('features.prechat_survey', false);
    olark('api.box.show');
    olark('api.box.expand');
  }

  function getUserInfo() {

    var user_info = {
      group: document.getElementById('chat-purdy-deparment').value,
      group_name: list_departments[document.getElementById('chat-purdy-deparment').value],
      name: document.getElementById('chat-purdy-name').value,
      email: document.getElementById('chat-purdy-email').value,
      id: document.getElementById('chat-purdy-document-number').value,
      phone: document.getElementById('chat-purdy-phone').value,
      plate: document.getElementById('chat-purdy-plate').value
    };

    return user_info;
  }

  function validateName() {
    var nameInput = document.getElementById('chat-purdy-name');
    if (nameInput.value === '') {
      var nameError = document.getElementById('error-chat-purdy-name');
      nameError.innerHTML = ERROR_REQUERIDO;
      nameError.classList.add("active");
      nameInput.classList.add("error");
      return false;
    }
    return true;
  }

  function validatePhone() {
    var phoneInput = document.getElementById('chat-purdy-phone');
    if (phoneInput.value === '') {
      var phoneError = document.getElementById('error-chat-purdy-phone');
      phoneError.innerHTML = ERROR_REQUERIDO;
      phoneError.classList.add("active");
      phoneInput.classList.add("error");
      return false;
    }
    return true;
  }

  function validateEmail() {
    var emailInput = document.getElementById('chat-purdy-email');
    var emailError = document.getElementById('error-chat-purdy-email');
    if (emailInput.value === '') {
      emailError.innerHTML = ERROR_REQUERIDO;
      emailError.classList.add("active");
      emailInput.classList.add("error");
      return false;
    }

    if (!validateEmailRE(emailInput.value)) {
      emailError.innerHTML = ERROR_EMAIL;
      emailError.classList.add("active");
      emailInput.classList.add("error");
      return false;
    }

    return true;
  }

  function validateEmailRE(email) {
    var re = /^([\w-]+(?:\.[\w-]+)*)@((?:[\w-]+\.)*\w[\w-]{0,66})\.([a-z]{2,6}(?:\.[a-z]{2})?)$/i;
    return re.test(email);
  }

  function timerChat() {
    var timerChatSw = true;
    var exitChattoyota = $('#evt-chat_purdy_close');
    var popupChat = $(".popup_chat");

    setTimeout(function() {
      popupChat.addClass('active');
      timerChatSw = false;
      //openChatForm();

    }, 2000);


    exitChattoyota.on('click', function() {
      var popupChat = $(".popup_chat");
      popupChat.removeClass('active');
    });
  }

  return {
    initialize: initialize,
    toggleForm: toggleForm
  };

})(window);


